<script lang="ts">
 import {untrack} from 'svelte';
 import type {ToolState} from '../../types';
 import Result from '../../components/Result.svelte';
 let {state:data=$bindable()}: {state:ToolState} = $props();
 import {onDestroy} from 'svelte';import {generate,trace} from './logic';untrack(()=>{data.names??='あかり\nひなた\nそら';data.prizes??='当たり\n参加賞\n特賞';data.board??=null;data.chosen??=0;data.revealed??=false;});let error=$state(''),running=$state(false),showPath=$state(false);let timer:ReturnType<typeof setTimeout>,startTimer:ReturnType<typeof setTimeout>;onDestroy(()=>{clearTimeout(timer);clearTimeout(startTimer);});function make(){clearTimeout(timer);clearTimeout(startTimer);running=false;showPath=false;try{data.board=generate(data.names,data.prizes);data.chosen=0;data.revealed=false;error='';}catch(e){error=(e as Error).message;}}function follow(){clearTimeout(timer);data.revealed=false;showPath=false;running=true;startTimer=setTimeout(()=>{showPath=true;},0);timer=setTimeout(()=>{running=false;data.revealed=true;},1500);}let height=$derived(data.board?120+data.board.edges.length*24:120);
</script>
<div class="form-grid"><label>参加者（1行に1人）<textarea bind:value={data.names} maxlength="1000" rows="5"></textarea></label><label>結果（1行に1つ）<textarea bind:value={data.prizes} maxlength="1000" rows="5"></textarea></label></div><div class="action-row"><button class="primary" onclick={make}>生成 / 再生成</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if data.board}<label>辿る参加者<select bind:value={data.chosen} disabled={running} onchange={()=>{showPath=false;data.revealed=false;}}>{#each data.board.participants as name,i}<option value={i}>{name}</option>{/each}</select></label><div class="action-row"><button onclick={follow} disabled={running}>線を辿る</button></div><div style="max-height:500px;overflow:auto;border:1px solid var(--line)"><svg role="img" aria-label="あみだくじの経路" width={data.board.participants.length*80} {height} viewBox={`0 0 ${data.board.participants.length*80} ${height}`} style="display:block;max-width:none"><title>あみだくじ。結果は下のテキストにも表示されます。</title>{#each data.board.participants as name,i}<line x1={40+i*80} y1="30" x2={40+i*80} y2={height-30} stroke="currentColor"/><text x={40+i*80} y="20" text-anchor="middle" font-size="11">{i+1}</text><text x={40+i*80} y={height-10} text-anchor="middle" font-size="11">{i+1}</text>{/each}{#each data.board.edges as edge,row}<line x1={40+edge*80} y1={60+row*24} x2={40+(edge+1)*80} y2={60+row*24} stroke="currentColor"/>{/each}{#if showPath}<polyline class="ladder-trace" points={trace(data.board,Number(data.chosen)).points} fill="none" stroke="var(--accent)" stroke-width="4" pathLength="1"/>{/if}</svg></div><p role="status">{running?'経路を辿っています…':data.revealed?`${data.board.participants[data.chosen]} → ${data.board.results[trace(data.board,Number(data.chosen)).end]}`:'参加者を選択して線を辿ってください。'}</p>{#if data.revealed}<Result text={data.board.participants.map((name:string,i:number)=>`${name} → ${data.board.results[trace(data.board,i).end]}`).join('\n')}/>{/if}{/if}<p class="tool-note">例：あかり・ひなた・そらの3人と、当たり・参加賞・特賞を各1行ずつ入力。2〜16人、各40文字。暗号学的乱数で結果の対応を均等にシャッフルし、重複交点のない隣接交換で経路を生成します。金銭・法的な抽選の証明には使用しないでください。</p><style>.ladder-trace{stroke-dasharray:1;stroke-dashoffset:0;animation:trace 1.5s linear}@keyframes trace{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}@media(prefers-reduced-motion:reduce){.ladder-trace{animation:none}}</style>
